#include <bits/stdc++.h>
using namespace std;

long long compute(long long n) {
    static unordered_map<long long, long long> cache;
    if (cache.count(n)) return cache[n];
    if (n <= 11) return min(n, 2 + (11 - n));
    long long x = 1, c = 1;
    while (x <= n) {
        x = x * 10 + 1;
        c++;
    }
    if (x > 2 * n) {
        long long quotient = n / (x / 10);
        long long remainder = n % (x / 10);
        return cache[n] = min(compute(x - n) + c, quotient * (c - 1) + compute(remainder));
    } else {
        long long quotient = n / (x / 10);
        long long remainder = n % (x / 10);
        return cache[n] = min(compute(x - n) + c, quotient * (c - 1) + compute(remainder));
    }
}

int main() {
    long long s;
    cin >> s;
    cout << compute(s);
    return 0;
}
